// image-source.ts: the test card's photo: the built-in sample, a viewer's own file, and the
// cover-fit drawing onto the image-area canvas.

import figureUrl from "./samples/figure.webp";

/** A decoded image the card can draw. */
export type CardImage = HTMLImageElement | ImageBitmap;

/** A built-in sample image. */
export interface SampleImage {
  /** Stable id, also used as the card's key. */
  id: string;
  /** Accessible name of its thumbnail button. */
  label: string;
  /** URL of the image file. */
  url: string;
}

/** The built-in samples. The figure was generated by the project author (MIT, like the repo). */
export const SAMPLE_IMAGES: readonly SampleImage[] = [
  { id: "figure", label: "Sample: chrome figure", url: figureUrl },
];

/** The message shown when a chosen or dropped file cannot be used. */
export const NOT_AN_IMAGE = "That file is not an image.";

/** The spec caps the canvas pixel ratio at 2 and keeps at least 160 px. */
const MAX_PIXEL_RATIO = 2;
const MIN_SIZE = 160;

/**
 * The source rectangle that covers a square target: the largest centered square of the image.
 *
 * @param width - Image width in pixels.
 * @param height - Image height in pixels.
 * @returns Source x, y and side length.
 */
export function coverSquare(width: number, height: number): { x: number; y: number; side: number } {
  const side = Math.min(width, height);
  return { x: (width - side) / 2, y: (height - side) / 2, side };
}

/**
 * Sizes a square canvas to its CSS width times the pixel ratio (capped at 2, at least 160 px).
 * Side effects: sets width and height, which clears the canvas.
 *
 * @param canvas - The laid-out canvas.
 * @param pixelRatio - The device pixel ratio.
 * @returns The side length in canvas pixels.
 */
export function sizeSquareCanvas(canvas: HTMLCanvasElement, pixelRatio: number): number {
  const ratio = Math.min(Math.max(pixelRatio, 1), MAX_PIXEL_RATIO);
  const size = Math.max(Math.round(canvas.clientWidth * ratio), MIN_SIZE);
  canvas.width = size;
  canvas.height = size;
  return size;
}

/**
 * Draws an image cover-fit on white (transparent parts read as light, as the grid sampling
 * expects). Side effects: resizes and redraws the canvas.
 *
 * @param canvas - The image-area canvas, already laid out.
 * @param image - The decoded image.
 * @param pixelRatio - The device pixel ratio.
 */
export function drawImageCover(
  canvas: HTMLCanvasElement,
  image: CardImage,
  pixelRatio: number,
): void {
  const size = sizeSquareCanvas(canvas, pixelRatio);
  const context = canvas.getContext("2d");
  if (!context) return;
  context.fillStyle = "#ffffff";
  context.fillRect(0, 0, size, size);
  const source = coverSquare(image.width, image.height);
  context.imageSmoothingQuality = "high";
  context.drawImage(image, source.x, source.y, source.side, source.side, 0, 0, size, size);
}

/**
 * Decodes a file the viewer chose or dropped.
 *
 * @param file - The file.
 * @returns The decoded image; rejects with {@link NOT_AN_IMAGE} for anything else.
 */
export async function loadImageFile(file: Blob): Promise<ImageBitmap> {
  if (!file.type.startsWith("image/")) throw new Error(NOT_AN_IMAGE);
  try {
    return await createImageBitmap(file);
  } catch {
    // A file named like an image that does not decode.
    throw new Error(NOT_AN_IMAGE);
  }
}

/**
 * Loads and decodes an image URL, such as a sample.
 *
 * @param url - The image URL.
 * @returns The decoded image element.
 */
export async function loadImageUrl(url: string): Promise<HTMLImageElement> {
  const image = new Image();
  image.src = url;
  await image.decode();
  return image;
}
